  const F = FLAVOR[ME] || {}, g = FLAVOR.generic;
  let h = 0; for (const c of ME) h = h * 31 + c.charCodeAt(0);
  CALLERS = F.callers || [0, 1, 2, 3, 4, 5].map(i => `${CALLER_NAMES[(h + i * 3) % CALLER_NAMES.length]} ${i % 2 ? 'in' : 'from'} ${m.places[(i + (i >> 2)) % m.places.length]}`);
  const voice = CALLERS[0], map = { CITY: TEAM.city, CITYU: TEAM.city.toUpperCase(), TEAM: TEAM.name, SHORT: TEAM.short, PARK: TEAM.park, RIVAL: rv[2], RIVALU: rv[2].toUpperCase(), AAA: AFF.AAA.n, VOICE: voice, VOICE1: voice.split(/ (?:from|in|on) /)[0], LGN: TEAM.lg === 'AL' ? 'American League' : 'National League', LGS: TEAM.lg, DIV: TEAM.div };
  const fill = s => s.replace(/\{([A-Z0-9]+)\}/g, (k, x) => map[x] != null ? map[x] : k);
